style.css:
@-moz-document domain("roblox.com") {
/* ==============================================
   ROBLOX ⋆˚࿔ TV Girl  Theme ⋆˚࿔ CUSTOM THEME V5.3
   Base code by ?Cloud Aurora?
   NEW Updated Sidebar section by @Aurora_Cloud
   ============================================== */

/* =========================================
   TV GIRL v2.1 — HOME GREETING OUTLINE
   ========================================= */

/* Greeting / username beside the Home avatar */
#HomeContainer h1:first-of-type,
#HomeContainer h1:first-of-type *,
#home-header .user-name-container,
#home-header .user-name-container *,
.home-header .user-name-container,
.home-header .user-name-container *,
.home-header h1,
.home-header h1 * {
    color: #f564b4 !important;

    -webkit-text-stroke: 7.7px rgba(255, 255, 255, 0.96) !important;
    paint-order: stroke fill !important;
}
  
/* =========================================
   PROFILE PAGE CODE
   ========================================= */

/* Colour of the Boxes */
.section-content.profile-header-content.ng-scope,
.rbx-tabs-horizontal .nav-tabs *,
.profile-avatar-mask,
.section.layer.profile-collections.ng-scope,
.switcher *,
.section.profile-statistics .section-content,
.btn-primary-md.ng-binding,
/* Additional bit for BTR */
.btr-header-status-parent,
.btr-profile-about > .section-content,
#games-switcher,
.btr-games-list .btr-game-button,
#roblox-badges-container > div:nth-child(2),
.btr-profile-playerbadges > div:nth-child(2),
.btr-profile-favorites > div:nth-child(2),
.btr-profile-groups > div:nth-child(2) {
    background-color: #0a4ea2C7 !important;
}

.section-content.profile-header-content.ng-scope,
.rbx-tabs-horizontal .nav-tabs *,
.profile-container .asset-item,
.switcher *,
.section.profile-statistics .section-content *,
.profile-about,
.btn-control-sm * {
    color: #ef268c !important;
}
/* End of the Boxes */

/* Profile Avatar Viewer */
.profile-avatar-left {
    background: transparent !important;
}
/* End of the Avatar Viewer */


/* =========================================
   CATALOG PAGE CODE
   ========================================= */

/* Creator Text */
.creator-name.text-link,
.text-robux-tile {
    color: white !important;
}
/* End of Creator */

/* Topics */
.topic.ng-binding.ng-scope {
    background-color: #1d439aCC !important;
    color: #73adff !important;
}
/* End of Topics */

/* Left Search Filters */
.search-options.ng-scope *,
.text-link.breadcrumb-link.ng-binding {
    color: #ea1c86 !important;
}
/* End of Left Search Filters */

/* Category Options Dropdown */
.input-dropdown-btn.category-options.ng-scope {
    color: #0a2c63 !important;
    background-color: #0a4ea2 !important;
}
/* End of Options Dropdown */

/* Catalog Searchbar */
.catalog-container .search-container .input-group .search-input,
.catalog-container .search-container .input-group .autocomplete-dropdown-menu .dropdown-menu {
    background-color: #3d94db !important;
    border-color: transparent !important;
    border-radius: 5px !important;
    color: #1e5c9e !important;
}
/* End of Searchbar */

/* Item Description */
#item-details-description {
    color: white !important;
}
/* End of Description */

/* Item Comment Section */
.section-content.AddAComment,
.comment-item * {
    background-color: #000000DE !important;
    color: #ea1c86 !important;
}
/* End of Comment Section */

/* Price Chart */
.section-content.price-volume-charts-container {
    background-color: #0a4ea2 !important;
}
/* End of Price Chart */


/* =========================================
   GAME PAGE CODE
   ========================================= */

/* Voting/Favourite/Follow Panel */
.favorite-follow-vote-share * {
    color: #0a4ea2 !important;
}
/* End of Panel */

/* Game Description */
.text.game-description.linkify,
.age-rating-details.col-xs-12.section-content *,
.age-recommendation-title,
.text-overflow.game-card-name-secondary {
    color: #f564b4 !important;
    font-weight: 480;
    backdrop-filter: blur(10px);
}
/* End of Description */

/* Game Stats */
.border-top.border-bottom.game-stats-container.follow-button-enabled,
.age-rating-details {
    background-color: #1e5c9e !important;
}

.border-top.border-bottom.game-stats-container.follow-button-enabled * {
    color: #3d94db !important;
    font-weight: 480;
}
/* End of Game Stats */

/* Servers/Badges */
.create-server-banner.section-content.remove-panel * {
    color: #800b3c !important;
    border-color: #800b3c !important;
    font-weight: 480;
}

.stack-row.badge-row.ng-scope,
.badge-image *,
.para-overflow.ng-binding,
.badge-stats-container *,
.btn-full-width.btn-control-sm.ng-binding,
.section.tab-server-only *,
.section-content-off.empty-game-instances-container,
.rbx-game-server-item *,
#sort-select,
.input *,
.section-content-off {
    background-color: #ea1c86 !important;
    color: #800b3c !important;
}

.section-content-off.empty-game-instances-container *,
.btn-more.rbx-refresh,
.server-list-options * {
    color: #ea1c86 !important;
}
/* End of Server/Badges */

/* Gamepasses */
.container-list.game-dev-store.game-passes * {
    color: #0a2c63 !important;
}

.store-card-footer {
    background-color: #1e5c9e !important;
    border-radius: 0px;
}
/* End of Gamepasses */


/* =========================================
   SETTINGS PAGE CODE
   ========================================= */

#user-account {
    backdrop-filter: blur(10px);
    backdrop-filter: invert(20%);
}

/* Sidebar Menu */
#vertical-menu {
    background-color: #ea1c86 !important;
}

#vertical-menu * {
    color: #f564b4 !important;
}
/* End of Sidebar Menu */

/* Text */
.text-label.account-settings-label,
.text-label.label-desktop.ng-binding,
#settings-container .rbx-tab-content * {
    color: #0a4ea2 !important;
}
/* End of Text */

/* Boxes */
#security-page-description,
.section-content.notifications-section,
.section-content.settings-security-setting-container,
.section-content.content-controls-section {
    background-color: #3d94db !important;
}
/* End of Boxes */


/* =========================================
   GROUPS PAGE CODE
   ========================================= */

/* Main Group Page */
.menu-option-content.group-card,
.rbx-divider,
.col-sm-9.ng-scope.col-xs-12.group-details > .ng-scope > .section-content,
.shout-container.section-content,
.section-content.group-members-list,
.section-content.group-wall,
.group-comments * {
    background-color: #0a4ea2E6 !important;
    color: #3d94db !important;
}

.group-description.toggle-target.ng-scope * {
    backdrop-filter: blur(10px);
    color: #061c4f !important;
}
/* End of Main Group Page */

/* Slideshow Arrows */
.carousel-control {
    opacity: 0.5;
}
/* End of Arrows */


/* =========================================
   AVATAR EDITOR PAGE CODE
   ========================================= */

/* Avatar Viewer */
.avatar-back {
    background: transparent !important;
}
/* End of Avatar Viewer */

/* Avatar Page Dropdown Menu */
.tab-horizontal-submenu.section-content.six-column {
    background-color: #ea1c86E6 !important;
}

.tab-horizontal-submenu.section-content.six-column * {
    color: #800b3c !important;
}
/* End of Avatar Editor Page Code */


/* =========================================
   GLOBAL BASE CODE
   ========================================= */

/* --- Credit signature (only ONE declaration) --- */
#navigation:after {
    position: absolute !important;
    content: "Updated Base Code by @Aurora_Cloud" !important;
    bottom: 5px !important;
    left: 10px !important;
    font-size: 8px !important;
}

.footer-note:after {
    content: " Hey there, this is a little secret from ?Cloud Aurora?/☁️Cloud Aurora☁️ or @Aurora_Cloud, the creator of this style's base code you're using.";
}

/* --- Ads be gone --- */
.ad,
.ad *,
.img_ad,
.ad-annotations,
#google_image_div,
#aw0,
#AdvertisingLeaderboard,
.abp .UpsellAdButton,
.abp .UpsellAdButton:link,
.abp .UpsellAdButton:visited,
.abp .BadAdButton,
.abp .BadAdButton:link,
.abp .BadAdButton:visited,
.abp .ad-identification-text,
a.ad img,
.abp,
.profile-ad,
#TopAbpContainer,
.ad-annotations,
#LeftGutterAdContainer,
#RightGutterAdContainer,
#Skyscraper-Adp-Right,
#Skyscraper-Adp-Left,
.abp-spacer,
#GamesListContainer1 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-even,
#GamesListContainer1 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-odd,
#GamesListContainer8 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-even,
#GamesListContainer8 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-odd,
.sponsored-game,
.alert-info,
#mCSB_1_container > ul > li.font-bold.small,
#mCSB_1_container > ul > li.rbx-nav-sponsor,
.banner-container,
#dialogs-minimize {
    visibility: hidden;
    background-color: transparent;
}
/* End of Ads */

/* --- Nostalgia nav labels (credits to Ologist) --- */
ul.nav:nth-child(2) > li:nth-child(1) > a:nth-child(1) {
    font-size: 0 !important;
}
ul.nav:nth-child(2) > li:nth-child(1) > a:nth-child(1)::before {
    content: "Games";
    font-size: 16px;
    color: #edc7dc !important;
}

ul.nav:nth-child(2) > li:nth-child(2) > a:nth-child(1) {
    font-size: 0 !important;
}
ul.nav:nth-child(2) > li:nth-child(2) > a:nth-child(1)::before {
    content: "Catalog";
    font-size: 16px;
    color: #edc7dc !important;
}

ul.nav:nth-child(2) > li:nth-child(3) > a:nth-child(1) {
    font-size: 0 !important;
}
ul.nav:nth-child(2) > li:nth-child(3) > a:nth-child(1)::before {
    content: "Develop";
    font-size: 16px;
    color: #edc7dc !important;
}

ul.nav:nth-child(2) > li:nth-child(4) > a:nth-child(1) {
    color: #edc7dc !important;
    padding: 6px !important;
}

/* Alignment fix */
.rbx-header .rbx-navbar li .nav-menu-title {
    padding: 3.2px !important;
}
/* Nostalgia code ends here */

/* --- Colour Customisation --- */

/* Header */
.rbx-header,
.age-bracket-label * {
    color: #edc7dc !important;
    background-color: #ea1c86 !important;
    border-color: #edc7dc !important;
}
/* End of Header */

/* Top Searchbar */
.navbar-search *,
.rbx-header .navbar-search .new-dropdown-menu,
.navbar-search .new-input-field {
    background-color: #800b3c !important;
    border-color: #800b3c !important;
    border-radius: 5px !important;
    color: #f564b4 !important;
}
/* End of Searchbar */

/* Left Sidebar (original) */
#navigation {
    background-color: #0a4ea2E3 !important;
}

.left-col-list * :not(.notification-blue),
.dynamic-overflow-container.text-nav {
    color: #061c4f !important;
}
/* End of Left Sidebar */

/* Get Premium Button */
.rbx-upgrade-now * {
    background-color: #3d94db !important;
}
/* End of Premium Button */

/* Footer */
.container-footer,
#footer-container * {
    background-color: #000000 !important;
    color: #800b3c !important;
}

#footer-container * {
    color: #800b3c !important;
}
/* End of Footer */

/* Chat */
.chat-body,
.chat-friend,
.chat-windows-header,
.dialogs * {
    background-color: #f564b4 !important;
    color: #ea1c86 !important;
}
/* End of Chat */

/* Thumbnails/placeholders */
.item-thumbnail-container *,
.accoutrement-item a {
    background-color: transparent !important;
    backdrop-filter: invert(4%);
}
/* End of Thumbnails */

/* Dropdown Menus */
.dropdown-menu,
.place-container,
.people-info-card-container .interaction-item,
#notification-stream-container *,
.select-option *,
.popover-content *,
.input-dropdown-btn {
    background-color: #ea1c86ED !important;
    color: #800b3c !important;
}

.arrow {
    border-bottom-color: #800b3c !important;
}
/* End of Dropdowns */

/* Input fields */
.select-group,
.input-field,
::placeholder {
    background-color: transparent !important;
    border-radius: 0px;
}
/* End of Input field */

/* Header Text */
h1,
h2,
.game-card-name,
.item-card-name,
.friend-name,
.btn-secondary-xs.btn-more.see-all-link-icon.ng-binding,
.text-name,
.text-robux-lg,
.btn-secondary-xs.see-all-link-icon.btn-more,
.text-label {
    color: #f564b4 !important;
}
/* End of Headers */

/* Like/dislike ratio and player count */
.vote-percentage-label,
.playing-counts-label {
    color: #f564b4 !important;
}
/* End of ratio and player count */

/* Colour of the Price */
.text-robux.ng-binding {
    color: #f564b4 !important;
}
/* End of Price */
/* Colour Customisation Ends */


/* =========================================
   BACKGROUND
   ========================================= */
/*Background*/
body, .content
   {
     background:transparent!important;
   }
.dark-theme, .light-theme, .nav-content
  {
     width: 100% !important;
     height: 100% !important;
     background-size: cover !important;
     background-attachment: fixed !important;
     /* Site it came from background-image: url(“”); */
     background-image: url("data:image/png;base64,")!important;
  }
/*End of Background*/

/* =========================================
   MODERN LEFT SIDEBAR (custom section)
   TV GIRL — revised notification handling
   ========================================= */


/* =========================================
   MAIN SIDEBAR
   ========================================= */

/* Main sidebar background */
#left-navigation-container .left-nav {
    background-color: #022947 !important;
}


/* Internal sidebar containers */
#left-navigation-container .left-nav > div,
#left-navigation-container .left-nav > div > div,
#left-navigation-container .left-nav > div > div > div {
    background-color: transparent !important;
}


/* =========================================
   NORMAL SIDEBAR LINKS
   ========================================= */

#left-navigation-container .left-nav nav a {
    background-color: #0a3870 !important;
    color: #ffffff !important;
}


/* Normal text */
#left-navigation-container .left-nav nav a span,
#left-navigation-container .left-nav nav a .text-truncate-end,
#left-navigation-container .left-nav nav a .ropro-sidebar-item-label,
#left-navigation-container .left-nav nav a .nav-item-text {
    color: #ffffff !important;
}


/* Normal icons */
#left-navigation-container .left-nav nav a svg,
#left-navigation-container .left-nav nav a .icon,
#left-navigation-container .left-nav nav a [role="presentation"] {
    color: #ffffff !important;
}


/* =========================================
   NOTIFICATION BUBBLES — NORMAL
   White bubble + BLUE number
   ========================================= */

#left-navigation-container .left-nav nav a[href*="messages"] .padding-x-small,
#left-navigation-container .left-nav nav a[href*="messages"] .padding-x-small span,
#left-navigation-container .left-nav nav a[href*="friends"] .padding-x-small,
#left-navigation-container .left-nav nav a[href*="friends"] .padding-x-small span {
    color: #0a3870 !important;
    -webkit-text-fill-color: #0a3870 !important;
    opacity: 1 !important;
    visibility: visible !important;
}


/* =========================================
   GENERAL HOVER
   ========================================= */

#left-navigation-container .left-nav nav a:hover {
    background-color: #ea1c86 !important;
    color: #f564b4 !important;
}


/* Pink text on hover */
#left-navigation-container .left-nav nav a:hover span,
#left-navigation-container .left-nav nav a:hover .text-truncate-end,
#left-navigation-container .left-nav nav a:hover .ropro-sidebar-item-label,
#left-navigation-container .left-nav nav a:hover .nav-item-text {
    color: #f564b4 !important;
}


/* Pink icons on hover — normal sidebar behavior */
#left-navigation-container .left-nav nav a:hover svg,
#left-navigation-container .left-nav nav a:hover .icon,
#left-navigation-container .left-nav nav a:hover .roseal-icon,
#left-navigation-container .left-nav nav a:hover [role="presentation"] {
    color: #f564b4 !important;
}


/* =========================================
   NOTIFICATION BUBBLES — HOVER
   White bubble + PINK number
   ========================================= */

#left-navigation-container .left-nav nav a[href*="messages"]:hover .padding-x-small,
#left-navigation-container .left-nav nav a[href*="messages"]:hover .padding-x-small span,
#left-navigation-container .left-nav nav a[href*="friends"]:hover .padding-x-small,
#left-navigation-container .left-nav nav a[href*="friends"]:hover .padding-x-small span {
    color: #f564b4 !important;
    -webkit-text-fill-color: #f564b4 !important;
}


/* =========================================
   ROBLOX HOVER OVERLAY
   ========================================= */

#left-navigation-container .left-nav nav a > div[role="presentation"] {
    background-color: transparent !important;
    z-index: 0 !important;
}


#left-navigation-container .left-nav nav a:hover > div[role="presentation"] {
    background-color: #ea1c86 !important;
}


#left-navigation-container .left-nav nav a > span {
    position: relative;
    z-index: 1 !important;
}


/* =========================================
   PROFILE LINK
   ========================================= */

#left-navigation-container .left-nav a[href="/users/profile"] {
    background-color: #0a3870 !important;
    color: #ffffff !important;
}


#left-navigation-container .left-nav a[href="/users/profile"] span {
    color: #ffffff !important;
}


#left-navigation-container .left-nav a[href="/users/profile"]:hover {
    background-color: #ea1c86 !important;
    color: #f564b4 !important;
}


#left-navigation-container .left-nav a[href="/users/profile"]:hover span {
    color: #f564b4 !important;
}


/* =========================================
   USERS LINK
   ========================================= */

#left-navigation-container .left-nav a[href="/users"] {
    background-color: #0a3870 !important;
    color: #ffffff !important;
}


#left-navigation-container .left-nav a[href="/users"] span {
    color: #ffffff !important;
}


#left-navigation-container .left-nav a[href="/users"]:hover {
    background-color: #ea1c86 !important;
    color: #f564b4 !important;
}


#left-navigation-container .left-nav a[href="/users"]:hover span {
    color: #f564b4 !important;
}


/* =========================================
   HOME LINK
   ========================================= */

#left-navigation-container .left-nav nav a[href*="/home"] {
    background-color: #0a3870 !important;
    color: #ffffff !important;
}


#left-navigation-container .left-nav nav a[href*="/home"]:hover {
    background-color: #ea1c86 !important;
    color: #f564b4 !important;
}


#left-navigation-container .left-nav nav a[href*="/home"]:hover span,
#left-navigation-container .left-nav nav a[href*="/home"]:hover .text-truncate-end {
    color: #f564b4 !important;
}


/* =========================================
   ROBLOX PLUS LINK
   ========================================= */

#left-navigation-container .left-nav nav a[href*="/plus"] {
    background-color: #0a3870 !important;
    color: #ffffff !important;
}


#left-navigation-container .left-nav nav a[href*="/plus"]:hover {
    background-color: #ea1c86 !important;
    color: #f564b4 !important;
}


#left-navigation-container .left-nav nav a[href*="/plus"]:hover span,
#left-navigation-container .left-nav nav a[href*="/plus"]:hover .text-truncate-end {
    color: #f564b4 !important;
}


/* =========================================
   SANDBOX LINK
   ========================================= */

#left-navigation-container .left-nav nav a[href*="/sandbox"] {
    background-color: #0a3870 !important;
    color: #ffffff !important;
}


/* Sandbox normal text */
#left-navigation-container .left-nav nav a[href*="/sandbox"] .ropro-sidebar-item-label,
#left-navigation-container .left-nav nav a[href*="/sandbox"] .nav-item-text {
    color: #ffffff !important;
}


/* Sandbox normal icon */
#left-navigation-container .left-nav nav a[href*="/sandbox"] .new-menu-icon.ropro-sidebar-icon,
