}


/* Sandbox hover */
#left-navigation-container .left-nav nav a[href*="/sandbox"]:hover {
    background-color: #ea1c86 !important;
    color: #f564b4 !important;
}


#left-navigation-container .left-nav nav a[href*="/sandbox"]:hover .ropro-sidebar-item-label,
#left-navigation-container .left-nav nav a[href*="/sandbox"]:hover .nav-item-text {
    color: #f564b4 !important;
}


/* Sandbox hover icon */
#left-navigation-container .left-nav nav a[href*="/sandbox"]:hover .new-menu-icon.ropro-sidebar-icon,
#left-navigation-container .left-nav nav a[href*="/sandbox"]:hover .new-menu-icon.ropro-sidebar-icon::before,
#left-navigation-container .left-nav nav a[href*="/sandbox"]:hover .new-menu-icon.ropro-sidebar-icon::after {
    color: #f564b4 !important;
    fill: #f564b4 !important;
    stroke: #f564b4 !important;
}


/* =========================================
   THEMES LINK
   ========================================= */

#left-navigation-container .left-nav nav a[href*="/themes"] {
    background-color: #0a3870 !important;
    color: #ffffff !important;
}


/* Themes normal text */
#left-navigation-container .left-nav nav a[href*="/themes"] .ropro-sidebar-item-label,
#left-navigation-container .left-nav nav a[href*="/themes"] .nav-item-text {
    color: #ffffff !important;
}


/* Themes normal icon */
#left-navigation-container .left-nav nav a[href*="/themes"] .new-menu-icon.ropro-sidebar-icon,
#left-navigation-container .left-nav nav a[href*="/themes"] .new-menu-icon.ropro-sidebar-icon::before,
#left-navigation-container .left-nav nav a[href*="/themes"] .new-menu-icon.ropro-sidebar-icon::after {
    color: #ffffff !important;
    fill: #ffffff !important;
    stroke: #ffffff !important;
}


/* Themes hover */
#left-navigation-container .left-nav nav a[href*="/themes"]:hover {
    background-color: #ea1c86 !important;
    color: #f564b4 !important;
}


#left-navigation-container .left-nav nav a[href*="/themes"]:hover .ropro-sidebar-item-label,
#left-navigation-container .left-nav nav a[href*="/themes"]:hover .nav-item-text {
    color: #f564b4 !important;
}


/* Themes hover icon */
#left-navigation-container .left-nav nav a[href*="/themes"]:hover .new-menu-icon.ropro-sidebar-icon,
#left-navigation-container .left-nav nav a[href*="/themes"]:hover .new-menu-icon.ropro-sidebar-icon::before,
#left-navigation-container .left-nav nav a[href*="/themes"]:hover .new-menu-icon.ropro-sidebar-icon::after {
    color: #f564b4 !important;
    fill: #f564b4 !important;
    stroke: #f564b4 !important;
}


/* =========================================
   FAVORITES LINKS
   ========================================= */

#left-navigation-container .left-nav nav a.nav-item-link {
    background-color: #0a3870 !important;
    color: #ffffff !important;
}


#left-navigation-container .left-nav nav a.nav-item-link .nav-item-text {
    color: #ffffff !important;
}


#left-navigation-container .left-nav nav a.nav-item-link .nav-item-icon,
#left-navigation-container .left-nav nav a.nav-item-link svg {
    color: #ffffff !important;
}


#left-navigation-container .left-nav nav a.nav-item-link:hover {
    background-color: #ea1c86 !important;
    color: #f564b4 !important;
}


#left-navigation-container .left-nav nav a.nav-item-link:hover .nav-item-text {
    color: #f564b4 !important;
}


#left-navigation-container .left-nav nav a.nav-item-link:hover .nav-item-icon,
#left-navigation-container .left-nav nav a.nav-item-link:hover svg {
    color: #f564b4 !important;
}


/* =========================================
   OFFICIAL STORE BUTTON
   ========================================= */

#left-navigation-container .left-nav nav button[type="button"] {
    background-color: #0a3870 !important;
    color: #ffffff !important;
}


#left-navigation-container .left-nav nav button[type="button"] span {
    color: #ffffff !important;
}


#left-navigation-container .left-nav nav button[type="button"]:hover {
    background-color: #ea1c86 !important;
    color: #f564b4 !important;
}


#left-navigation-container .left-nav nav button[type="button"]:hover span {
    color: #f564b4 !important;
}


#left-navigation-container .left-nav nav button[type="button"]:hover svg,
#left-navigation-container .left-nav nav button[type="button"]:hover .icon {
    color: #f564b4 !important;
}


/* =========================================
   FINAL LAYER FIX
   ========================================= */

#left-navigation-container .left-nav nav a:hover > span,
#left-navigation-container .left-nav nav button:hover > span {
    position: relative;
    z-index: 2 !important;
}


/* =========================================
   MESSAGES + FRIENDS ICON LOCK
   ALWAYS WHITE
   ========================================= */

/*
   These rules deliberately come LAST.

   The notification bubble has already been
   separated above using .padding-x-small.

   These selectors affect only icon elements,
   so the BLUE/PINK notification number is
   allowed to remain independent.
*/

#left-navigation-container .left-nav nav a[href*="messages"] svg,
#left-navigation-container .left-nav nav a[href*="messages"] .icon,
#left-navigation-container .left-nav nav a[href*="messages"] [class*="icon-"],

#left-navigation-container .left-nav nav a[href*="friends"] svg,
#left-navigation-container .left-nav nav a[href*="friends"] .icon,
#left-navigation-container .left-nav nav a[href*="friends"] [class*="icon-"] {
    color: #ffffff !important;
}


/* Messages/Friends icons remain WHITE on hover */
#left-navigation-container .left-nav nav a[href*="messages"]:hover svg,
#left-navigation-container .left-nav nav a[href*="messages"]:hover .icon,
#left-navigation-container .left-nav nav a[href*="messages"]:hover [class*="icon-"],

#left-navigation-container .left-nav nav a[href*="friends"]:hover svg,
#left-navigation-container .left-nav nav a[href*="friends"]:hover .icon,
#left-navigation-container .left-nav nav a[href*="friends"]:hover [class*="icon-"] {
    color: #ffffff !important;
}


/* =========================================
   NOTIFICATION COLOR — FINAL AUTHORITY
   ========================================= */

/* NORMAL = BLUE number */
#left-navigation-container .left-nav nav a[href*="messages"] .padding-x-small,
#left-navigation-container .left-nav nav a[href*="messages"] .padding-x-small *,
#left-navigation-container .left-nav nav a[href*="friends"] .padding-x-small,
#left-navigation-container .left-nav nav a[href*="friends"] .padding-x-small * {
    color: #0a3870 !important;
    -webkit-text-fill-color: #0a3870 !important;
}


/* HOVER = PINK number */
#left-navigation-container .left-nav nav a[href*="messages"]:hover .padding-x-small,
#left-navigation-container .left-nav nav a[href*="messages"]:hover .padding-x-small *,
#left-navigation-container .left-nav nav a[href*="friends"]:hover .padding-x-small,
#left-navigation-container .left-nav nav a[href*="friends"]:hover .padding-x-small * {
    color: #f564b4 !important;
    -webkit-text-fill-color: #f564b4 !important;
}


